/* Called by the HTTP adapter for one submitted login attempt. */
int auth_submit(const struct login_attempt *attempt,
                void (*on_failure)(void *, const char *),
                void *context)
{
    struct account_record record;

    if (!account_lookup(attempt->login_id, &record)) {
        on_failure(context, attempt->login_id);
        return AUTH_REJECTED;
    }

    if (!password_matches(attempt->password, record.password_hash)) {
        on_failure(context, attempt->login_id);
        return AUTH_REJECTED;
    }

    return AUTH_ACCEPTED;
}
